import Link from "next/link";
import { getSessionUser } from "@/lib/auth";
import SignOutButton from "@/components/SignOutButton";

export const dynamic = "force-dynamic";

export default async function HomePage() {
  const user = await getSessionUser();

  return (
    <main
      style={{
        minHeight: "100vh",
        padding: "2rem",
        fontFamily: "system-ui, sans-serif",
        background: "linear-gradient(135deg, #7C5CFF 0%, #5AC8FA 100%)",
      }}
    >
      <header
        style={{
          display: "flex",
          justifyContent: "space-between",
          alignItems: "center",
          maxWidth: "60rem",
          margin: "0 auto",
        }}
      >
        <h1 style={{ margin: 0, fontSize: "1.5rem", color: "#fff" }}>
          🎉 Confetti Club
        </h1>
        <nav style={{ display: "flex", gap: "0.75rem", alignItems: "center" }}>
          {user ? (
            <>
              {user.role === "admin" && (
                <Link
                  href="/admin"
                  style={{
                    padding: "0.5rem 1rem",
                    borderRadius: "0.5rem",
                    background: "rgba(255,255,255,0.2)",
                    color: "#fff",
                    fontSize: "0.875rem",
                    textDecoration: "none",
                  }}
                >
                  Admin
                </Link>
              )}
              <SignOutButton />
            </>
          ) : (
            <>
              <Link
                href="/auth/signin"
                style={{ color: "#fff", fontSize: "0.875rem" }}
              >
                Sign in
              </Link>
              <Link
                href="/auth/signup"
                style={{
                  padding: "0.5rem 1rem",
                  borderRadius: "0.5rem",
                  background: "#fff",
                  color: "#7C5CFF",
                  fontSize: "0.875rem",
                  textDecoration: "none",
                  fontWeight: 600,
                }}
              >
                Create account
              </Link>
            </>
          )}
        </nav>
      </header>

      <section
        style={{
          maxWidth: "60rem",
          margin: "4rem auto 0",
          color: "#fff",
          textAlign: "center",
        }}
      >
        <h2 style={{ fontSize: "2.5rem", margin: 0 }}>
          Gifts that actually land.
        </h2>
        <p style={{ fontSize: "1.125rem", opacity: 0.9, marginTop: "0.75rem" }}>
          A curated shop of personalized, tech, and cozy finds — gift-ready in
          our signature confetti box.
        </p>
        {user && (
          <p style={{ marginTop: "1.5rem", fontSize: "0.875rem", opacity: 0.85 }}>
            Signed in as {user.email} ({user.role})
          </p>
        )}
      </section>
    </main>
  );
}
